// Known-answer tests against the shared vectors generated by the Go server
// (internal/e2ee/vectors_test.go) and verified by the web app's crypto.test.ts.
// If these pass, this client's cryptography is byte-compatible with both.

import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:opentodo_flutter/core/e2ee.dart';

Uint8List hex(String s) {
  final out = Uint8List(s.length ~/ 2);
  for (var i = 0; i < out.length; i++) {
    out[i] = int.parse(s.substring(i * 2, i * 2 + 2), radix: 16);
  }
  return out;
}

String toHex(Uint8List b) =>
    b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();

void main() {
  final vectors =
      jsonDecode(File('test/vectors/e2ee.vectors.json').readAsStringSync())
          as Map<String, dynamic>;

  group('content values', () {
    final cases = (vectors['content'] as List).cast<Map<String, dynamic>>();
    for (final c in cases) {
      final key = hex(c['key'] as String);
      final entity = c['entity'] as String;
      final entityId = c['entityId'] as String;
      final field = c['field'] as String;
      final plaintext = c['plaintext'] as String;
      final expected = c['value'] as String;

      test('$entity.$field "$plaintext" encrypts to the vector', () {
        final got = encryptValue(key, entity, entityId, field, plaintext,
            nonce: hex(c['nonce'] as String));
        expect(got, expected);
      });

      test('$entity.$field decrypts the vector', () {
        expect(decryptValue(key, entity, entityId, field, expected), plaintext);
      });
    }

    test('a tampered envelope fails authentication', () {
      final c = cases.first;
      final key = hex(c['key'] as String);
      final value = c['value'] as String;
      // Flip one character of the ciphertext body.
      final i = value.length - 5;
      final ch = value[i] == 'A' ? 'B' : 'A';
      final tampered = value.substring(0, i) + ch + value.substring(i + 1);
      expect(
        () => decryptValue(key, c['entity'] as String, c['entityId'] as String,
            c['field'] as String, tampered),
        throwsA(isA<DecryptError>()),
      );
    });

    test('a value moved to another field fails authentication', () {
      final c = cases.first;
      expect(
        () => decryptValue(hex(c['key'] as String), c['entity'] as String,
            c['entityId'] as String, 'description', c['value'] as String),
        throwsA(isA<DecryptError>()),
      );
    });

    test('a wrong key fails authentication', () {
      final c = cases.first;
      final wrong = Uint8List(32);
      expect(
        () => decryptValue(wrong, c['entity'] as String, c['entityId'] as String,
            c['field'] as String, c['value'] as String),
        throwsA(isA<DecryptError>()),
      );
    });

    test('envelope detection is stricter than the ciphertext prefix', () {
      expect(isCiphertext('enc:hello'), true);
      expect(isEnvelope('enc:hello'), false);
      expect(isEnvelope(cases.first['value'] as String), true);
      expect(isEnvelope('enc:v1:short'), false);
    });
  });

  group('passphrase wrap (PBKDF2 + AES-KW)', () {
    final p = vectors['passphrase'] as Map<String, dynamic>;
    final accountKey = hex(p['accountKey'] as String);

    test('wraps to the vector', () {
      final kek = derivePassphraseKey(
          p['passphrase'] as String, hex(p['salt'] as String), p['iterations'] as int);
      expect(wrapAccountKey(accountKey, kek), p['wrapped']);
    });

    test('unwraps the vector', () {
      final kek = derivePassphraseKey(
          p['passphrase'] as String, hex(p['salt'] as String), p['iterations'] as int);
      expect(toHex(unwrapAccountKey(p['wrapped'] as String, kek)), p['accountKey']);
    });

    test('a wrong passphrase is refused', () {
      final kek = derivePassphraseKey(
          'wrong passphrase', hex(p['salt'] as String), p['iterations'] as int);
      expect(() => unwrapAccountKey(p['wrapped'] as String, kek),
          throwsA(isA<WrongSecretError>()));
    });

    test('NFC normalization: decomposed passphrase matches composed', () {
      final salt = hex(p['salt'] as String);
      // "café" composed (U+00E9) vs decomposed (e + U+0301).
      final a = derivePassphraseKey('caf\u00e9', salt, 1000);
      final b = derivePassphraseKey('cafe\u0301', salt, 1000);
      expect(toHex(a), toHex(b));
    });
  });

  group('recovery key (HKDF + AES-KW + base32)', () {
    final r = vectors['recovery'] as Map<String, dynamic>;
    final raw = hex(r['raw'] as String);

    test('formats to the vector text', () {
      expect(formatRecoveryKey(raw), r['text']);
    });

    test('parses the vector text back', () {
      expect(toHex(parseRecoveryKey(r['text'] as String)), r['raw']);
    });

    test('parse ignores case, spaces and dashes, maps 0/1/8', () {
      final messy = (r['text'] as String).toLowerCase().replaceAll('-', ' ');
      expect(toHex(parseRecoveryKey(messy)), r['raw']);
    });

    test('a bad checksum is refused', () {
      final text = r['text'] as String;
      final last = text[text.length - 1] == 'A' ? 'B' : 'A';
      expect(() => parseRecoveryKey(text.substring(0, text.length - 1) + last),
          throwsA(isA<RecoveryKeyFormatError>()));
    });

    test('wraps the account key to the vector', () {
      final kek = deriveRecoveryKey(raw);
      expect(wrapAccountKey(hex(r['accountKey'] as String), kek), r['wrapped']);
      expect(toHex(unwrapAccountKey(r['wrapped'] as String, kek)), r['accountKey']);
    });
  });

  group('key record lifecycle', () {
    setUp(() {
      iterationLimitMin = 1000; // derive keys quickly in tests
    });
    tearDown(() {
      iterationLimitMin = acceptedIterationsMin;
    });

    test('create, unlock with passphrase and recovery key', () {
      final created = createKeyRecord('correct horse battery staple', iterations: 1000);
      expect(created.record.version, 1);
      expect(created.record.kdf, kdfPbkdf2Sha256);
      expect(created.recoveryKey.split('-').length, 14);
      final byPass = unlockWithPassphrase(created.record, 'correct horse battery staple');
      expect(toHex(byPass), toHex(created.key));
      final byRecovery = unlockWithRecoveryKey(created.record, created.recoveryKey);
      expect(toHex(byRecovery), toHex(created.key));
    });

    test('rewrap keeps the key and the recovery wrap', () {
      final created = createKeyRecord('correct horse battery staple', iterations: 1000);
      final next = rewrapWithPassphrase(
          created.record, 'correct horse battery staple', 'a new passphrase!!',
          iterations: 1000);
      expect(next.version, 2);
      expect(next.wrappedByRecovery, created.record.wrappedByRecovery);
      expect(toHex(unlockWithPassphrase(next, 'a new passphrase!!')), toHex(created.key));
      expect(toHex(unlockWithRecoveryKey(next, created.recoveryKey)), toHex(created.key));
    });

    test('reset with recovery key rotates the recovery key', () {
      final created = createKeyRecord('correct horse battery staple', iterations: 1000);
      final reset = resetWithRecoveryKey(
          created.record, created.recoveryKey, 'another passphrase!',
          iterations: 1000);
      expect(toHex(unlockWithPassphrase(reset.record, 'another passphrase!')),
          toHex(created.key));
      expect(toHex(unlockWithRecoveryKey(reset.record, reset.recoveryKey)),
          toHex(created.key));
      expect(() => unlockWithRecoveryKey(reset.record, created.recoveryKey),
          throwsA(isA<WrongSecretError>()));
    });

    test('iteration floor is enforced', () {
      final record = KeyRecord(
        version: 1,
        kdf: kdfPbkdf2Sha256,
        salt: b64url(Uint8List(16)),
        iterations: 10,
        wrappedByPassphrase: '',
        wrappedByRecovery: '',
      );
      expect(() => unlockWithPassphrase(record, 'whatever passphrase'),
          throwsA(isA<KeyRecordParamsError>()));
    });
  });

  group('attachment files', () {
    final f = vectors['file'] as Map<String, dynamic>;
    final key = hex(f['key'] as String);
    final id = f['id'] as String;
    final plain = utf8.encode(f['plaintext'] as String);

    test('encrypts to the vector envelope', () {
      final got = encryptFile(key, id, Uint8List.fromList(plain),
          prefixBytes: hex(f['prefix'] as String), chunkSize: f['chunkSize'] as int);
      expect(toHex(got), f['envelope']);
    });

    test('decrypts the vector envelope', () {
      final got = decryptFile(key, id, hex(f['envelope'] as String));
      expect(utf8.decode(got), f['plaintext']);
    });

    test('a wrong id fails', () {
      expect(() => decryptFile(key, 'other', hex(f['envelope'] as String)),
          throwsA(isA<DecryptError>()));
    });

    test('a truncated envelope fails', () {
      final env = hex(f['envelope'] as String);
      expect(() => decryptFile(key, id, env.sublist(0, env.length - 4)),
          throwsA(isA<DecryptError>()));
    });

    test('multi-chunk round trip with a random prefix', () {
      final big = Uint8List(1024 * 1024 + 7); // over one 1 MiB chunk
      for (var i = 0; i < big.length; i++) {
        big[i] = i % 251;
      }
      final env = encryptFile(key, id, big);
      expect(toHex(decryptFile(key, id, env)), toHex(big));
    });

    test('empty file round trip', () {
      final env = encryptFile(key, id, Uint8List(0));
      expect(decryptFile(key, id, env).length, 0);
    });
  });

  group('content layer', () {
    final key = hex(vectors['content'][0]['key'] as String);

    test('content fields follow the schema', () {
      expect(isContentField('task', 'title'), true);
      expect(isContentField('task', 'priority'), false);
      expect(isContentField('task', 'fields.f1'), true);
      expect(isContentField('task', 'appends.a1'), true);
      expect(isContentField('note', 'appends.a1'), true);
      expect(isContentField('note', 'title'), true);
      expect(isContentField('label', 'name'), true);
      expect(isContentField('label', 'color'), false);
    });

    test('seal and open a string value', () {
      final sealed = sealValue(key, 'task', 't9', 'title', 'Buy milk');
      expect(isEnvelope(sealed), true);
      expect(openValue(key, 'task', 't9', 'title', sealed), 'Buy milk');
    });

    test('non-content and empty values pass through', () {
      expect(sealValue(key, 'task', 't9', 'priority', 1), 1);
      expect(sealValue(key, 'task', 't9', 'title', ''), '');
      expect(sealValue(key, 'task', 't9', 'title', null), null);
      expect(sealValue(key, 'task', 't9', 'completed_at', 123), 123);
    });

    test('object content (origin) seals as JSON and opens as a map', () {
      final origin = {'kind': 'url', 'url': 'https://example.com'};
      final sealed = sealValue(key, 'task', 't9', 'origin', origin);
      expect(isEnvelope(sealed), true);
      expect(openValue(key, 'task', 't9', 'origin', sealed), origin);
    });

    test('an already-sealed value is not sealed twice', () {
      final sealed = sealValue(key, 'task', 't9', 'title', 'Buy milk');
      expect(sealValue(key, 'task', 't9', 'title', sealed), sealed);
    });

    test('numbers in fields.* stay plaintext', () {
      expect(sealValue(key, 'task', 't9', 'fields.n', 42), 42);
      expect(sealValue(key, 'task', 't9', 'fields.b', true), true);
    });
  });
}
